// Extract message ids; emit one item per message (or none if no unread).
const data = $input.item.json || {};
const messages = Array.isArray(data.messages) ? data.messages : [];
return messages.map(m => ({ json: { id: m.id, threadId: m.threadId } }));

// Extract sender email + subject + snippet from Gmail response.
const msg = $input.item.json || {};
const headers = (msg.payload && msg.payload.headers) || [];

function h(name) {
  const hit = headers.find(x => x.name && x.name.toLowerCase() === name.toLowerCase());
  return hit ? hit.value : '';
}

const fromRaw = h('From');
const match = fromRaw.match(/<([^>]+)>/);
const fromEmail = (match ? match[1] : fromRaw).trim().toLowerCase();

return { json: { gmail_message_id: msg.id, thread_id: msg.threadId, from_email: fromEmail, subject: h('Subject'), in_reply_to: h('In-Reply-To'), snippet: msg.snippet || '', internal_date: msg.internalDate } };

// Decide whether we have a matching lead worth processing.
const gmail = $('Extract Sender').item.json;
const rows = $input.item.json;
const lead = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
if (!lead || !lead.id) return { json: { ...gmail, matched: false, skip_reason: 'no_matching_lead' } };
if (lead.total_emails_sent === 0) return { json: { ...gmail, matched: false, skip_reason: 'unsolicited_inbound' } };
return { json: { ...gmail, matched: true, lead_id: lead.id, client_id: lead.client_id, full_name: lead.full_name, company: lead.company, current_status: lead.lead_status } };

// Classify an inbound reply, and honour a stop request.
//
// WHY THIS IS DETERMINISTIC AND NOT A MODEL CALL
//
// Nothing in this estate has ever set a suppression flag. Both outbound
// templates print "reply STOP to unsubscribe"; no code has ever read a
// reply looking for it. A reply saying STOP was written as lead_status
// 'Replied', which made the lead ELIGIBLE for the booking sweep, which
// could then email it a Calendly link. We promised a way out and built
// the opposite.
//
// Honouring that promise is a legal obligation under CASL, not a feature.
// It therefore cannot depend on a model being reachable, in credit, or
// returning parseable JSON. Rules run every time, cost nothing, and are
// testable. Nuance can be layered on later; suppression cannot wait for it.
//
// PRECEDENCE MATTERS. A reply reading "not interested, please remove me"
// is an unsubscribe first and a rejection second. Categories are checked
// most-binding first and the first match wins.
//
// What we classify is Gmail's `snippet` -- roughly the first 200
// characters, because Get Message Metadata does not fetch the body. That
// is where people put "STOP" and "wrong person", so it serves this job,
// and UNCLEAR is returned honestly when it does not.

const item = $input.item.json;
const text = String(item.snippet || '') + ' ' + String(item.subject || '');
const t = ' ' + text.toLowerCase().replace(/[^a-z0-9@'\s]/g, ' ').replace(/\s+/g, ' ') + ' ';

function any(patterns) {
  for (var i = 0; i < patterns.length; i++) {
    if (patterns[i].test(t)) return true;
  }
  return false;
}

// Ordered. First match wins.
const RULES = [
  ['UNSUBSCRIBE', [
    /\bstop\b/, /\bunsubscribe\b/, /\bopt ?out\b/, /\bremove me\b/,
    /\btake me off\b/, /\bdo not (e ?mail|contact|write)\b/,
    /\bdon'?t (e ?mail|contact) me\b/, /\bno longer wish\b/,
    /\bdelete my (data|details|information)\b/]],

  ['WRONG_PERSON', [
    /\bwrong person\b/, /\bnot the right person\b/, /\bno longer (work|with)\b/,
    /\bi (have )?left\b/, /\bnot my (area|department|role)\b/,
    /\bspeak to\b/, /\bforward(ed|ing)? (this )?to\b/, /\btry (contacting|reaching)\b/]],

  ['ALREADY_HAS_PROVIDER', [
    /\balready (have|use|using|working with|got)\b/, /\bwe have a (provider|supplier|partner|vendor|agency)\b/,
    /\bunder contract\b/, /\bhappy with (our|my)\b/, /\bsorted\b/]],

  ['BOOK_MEETING', [
    /\bbook (a )?(call|meeting|time)\b/, /\bschedule (a )?(call|meeting)\b/,
    /\bset up a (call|meeting|time)\b/, /\bcalendar\b/, /\bwhat times?\b/,
    /\bavailable (on|at|this|next)\b/]],

  ['PRICING', [
    /\bprice\b/, /\bpricing\b/, /\bhow much\b/, /\bcost\b/, /\bquote\b/,
    /\brates?\b/, /\bfees?\b/, /\bbudget\b/]],

  ['SEND_INFORMATION', [
    /\bsend (me )?(more )?(info|information|details|a deck|brochure)\b/,
    /\bmore (info|information|details)\b/, /\bwhat do you (do|offer)\b/,
    /\bliterature\b/, /\bcase stud/]],

  ['CALL_LATER', [
    /\bnot (right )?now\b/, /\blater\b/, /\bnext (month|quarter|year|week)\b/,
    /\bcheck back\b/, /\bcircle back\b/, /\breach out in\b/, /\bfollow up in\b/,
    /\bcurrently (busy|tied up)\b/, /\bbad time\b/]],

  ['NOT_INTERESTED', [
    /\bnot interested\b/, /\bno thanks?\b/, /\bno thank you\b/,
    /\bnot for us\b/, /\bnot a (fit|good fit)\b/, /\bpass\b/,
    /\bwe'?re (all )?good\b/, /\bdecline\b/]],

  ['QUESTION', [
    /\?/, /\bhow (do|does|would|can)\b/, /\bwhat (is|are|would)\b/,
    /\bcan you (explain|clarify|tell)\b/, /\bwhich\b/]],

  ['INTERESTED', [
    /\binterested\b/, /\bsounds good\b/, /\btell me more\b/, /\byes\b/,
    /\bkeen\b/, /\blet'?s (talk|chat|discuss)\b/, /\bhappy to\b/]]
];

let category = 'UNCLEAR';
for (var i = 0; i < RULES.length; i++) {
  if (any(RULES[i][1])) { category = RULES[i][0]; break; }
}

// What each category means for the funnel. Only two suppress, and both
// suppress via do_not_contact -- the flag every send path actually filters
// on (Outreach Sender, Follow Up and Booking all carry
// do_not_contact=eq.false). `unsubscribed` is the semantically nicer
// column but update_lead's allowlist does not include it, so relying on it
// would mean writing a flag nothing enforces.
const SUPPRESS  = { UNSUBSCRIBE: true };
const STATUS = {
  UNSUBSCRIBE:          'Do Not Contact',
  NOT_INTERESTED:       'Not Interested',
  ALREADY_HAS_PROVIDER: 'Not Interested'
};
// Everything else stays 'Replied': a human decides, and the lead stops
// being chased either way because follow-up filters on reply_detected.

const suppress = SUPPRESS[category] === true;

console.log('[reply] ' + (item.from_email || '?') + ' -> ' + category +
            (suppress ? ' (SUPPRESSED)' : ''));

return { json: Object.assign({}, item, {
  reply_category: category,
  suppress: suppress,
  new_status: STATUS[category] || 'Replied',
  // Recorded so a misclassification can be audited against what arrived,
  // rather than argued about from memory.
  classified_on: String(item.snippet || '').slice(0, 300)
}) };
